import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"运行环境与脚本加载","description":"","frontmatter":{},"headers":[],"relativePath":"development/lua/environment.md","filePath":"development/lua/environment.md","lastUpdated":1791683719000}`),a={name:`development/lua/environment.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="运行环境与脚本加载" tabindex="-1">运行环境与脚本加载 <a class="header-anchor" href="#运行环境与脚本加载" aria-label="Permalink to “运行环境与脚本加载”">​</a></h1><h2 id="lua-环境" tabindex="-1">Lua 环境 <a class="header-anchor" href="#lua-环境" aria-label="Permalink to “Lua 环境”">​</a></h2><p>当前使用 GopherLua，支持 Lua 5.1 语法、Lua 5.2 的 <code>goto</code> 语句，以及独有的 <a href="https://github.com/yuin/gopher-lua#lua-api" target="_blank" rel="noreferrer"><code>channel</code></a>。</p><p>Xray 根据配置文件加载 Lua 脚本。配置的位置决定脚本用于什么功能，不同位置加载的脚本可用的 Hook 也不同。各入口可用的 Hook 及其调用约定见 <a href="./#hook">Hook 参考</a>。</p><h2 id="模块加载" tabindex="-1">模块加载 <a class="header-anchor" href="#模块加载" aria-label="Permalink to “模块加载”">​</a></h2><p>API 模块按功能组织，通过 <code>require</code> 加载：</p><div class="language-lua line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> geodata</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.geodata&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span>
<span class="line"><span style="--shiki-dark:#569CD6;--shiki-light:#0000FF;">local</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> log</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> = </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">require</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">(</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;xray.log&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>模块列表见<a href="./#模块-api">模块 API</a>，各函数的用法见对应 API 参考。</p><p>加载 Lua 模块、创建对象等顶层初始化的执行时机，见<a href="./guide/lifecycle.html">实例与生命周期</a>。</p><h2 id="脚本文件路径" tabindex="-1">脚本文件路径 <a class="header-anchor" href="#脚本文件路径" aria-label="Permalink to “脚本文件路径”">​</a></h2><p>配置文件中的 <code>script</code> 字段用于指定 Lua 脚本文件的路径。空字符串或未配置表示不启用脚本；绝对路径直接定位文件。</p><p>相对路径按以下顺序查找；路径不存在时继续，存在但不是普通文件时立即报错：</p><ol><li>环境变量 <code>XRAY_LOCATION_CONFDIR</code> 指定的目录；</li><li>环境变量 <code>XRAY_LOCATION_CONFIG</code> 指定的目录；</li><li>Xray 进程的当前工作目录；</li><li>Xray 可执行文件所在目录。</li></ol><p>这些目录的设置见<a href="./../../config/env.html">环境变量</a>。相对路径不会自动以配置文件所在目录为基准。</p><p>例如，将脚本路径设为 <code>routing.lua</code> 后，Xray 会按上述顺序查找文件。Windows 绝对路径可以写成 <code>C:/Xray/routing.lua</code>；使用反斜杠时，请按所用配置格式的要求进行转义。</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};